package com.qingji.ledger

import org.junit.Assert.*
import org.junit.Test
import org.json.JSONObject
import java.time.LocalDate

class BackupCodecTest {
    private fun sample():Snapshot { val cats=defaultCategories();val e=Entry(id="original",type=EXPENSE,amount=10000,categoryId="expense-0",date="2026-11-01");val r=Entry(id="refund",type=REFUND,amount=3000,categoryId="expense-0",date="2026-11-09",refundOf=e.id);return Snapshot(listOf(e,r),cats,listOf(Budget("2026-11","",500000)),listOf(Goal(id="g",title="旅行",target=600000)),listOf(GoalEvent(id="g1",goalId="g",amount=10000,date="2026-11-01",createdAt=1),GoalEvent(id="g2",goalId="g",amount=-1000,date="2026-11-02",createdAt=2)),Settings(),true) }
    @Test fun completeRoundTrip(){val s=sample();val restored=BackupCodec.decode(BackupCodec.encode(s));assertEquals(s.entries,restored.entries);assertEquals(s.categories,restored.categories);assertEquals(s.budgets,restored.budgets);assertEquals(s.goals,restored.goals);assertEquals(s.events,restored.events);assertEquals(9000L,restored.progress("g"))}
    @Test fun futureVersionIsRejected(){val root=JSONObject(BackupCodec.encode(sample())).put("schemaVersion",999);assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())}}
    @Test fun fractionalCentAndRefundOverflowRejected(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONArray("entries").getJSONObject(0).put("amount",10000.5);assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())};val overflow=JSONObject(BackupCodec.encode(sample()));overflow.getJSONArray("entries").getJSONObject(1).put("amount",10001);assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(overflow.toString())}}
    @Test fun duplicateIdsAndBrokenReferencesRejected(){val root=JSONObject(BackupCodec.encode(sample()));val entries=root.getJSONArray("entries");entries.put(entries.getJSONObject(0));assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())};val broken=JSONObject(BackupCodec.encode(sample()));broken.getJSONArray("entries").getJSONObject(1).put("refundOf","missing");assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(broken.toString())}}
    @Test fun savingsCannotBeNegative(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONArray("events").getJSONObject(1).put("amount",-20000);assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())}}
    @Test fun csvEscapesQuotesNewlinesAndFormula(){val s=sample().let{it.copy(entries=it.entries.map{e->e.copy(note="=SUM(A1)\n\"quoted\"")})};val csv=BackupCodec.csv(s,DateRange(LocalDate.of(2026,11,1),LocalDate.of(2026,11,30)));assertTrue(csv.startsWith("\uFEFF"));assertTrue(csv.contains("'=SUM(A1)"));assertTrue(csv.contains("\"\"quoted\"\""))}
    @Test fun budgetFlagsRoundTrip(){val s=sample().let{it.copy(entries=it.entries.map{e->if(e.id=="original")e.copy(inBudget=false,repayment=true,pool=POOL_INVEST)else e})};val restored=BackupCodec.decode(BackupCodec.encode(s));val origin=restored.entries.first{it.id=="original"};assertFalse(origin.inBudget);assertTrue(origin.repayment);assertEquals(POOL_INVEST,origin.pool);assertEquals(0L,budgetExpense(restored.entries))}
    @Test fun legacyBackupUsesEmptyBudgetFlags(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONObject("settings").remove("budgetExcludedEntries");root.getJSONObject("settings").remove("repaymentEntries");val restored=BackupCodec.decode(root.toString());assertTrue(restored.settings.budgetExcludedEntries.isEmpty());assertTrue(restored.settings.repaymentEntries.isEmpty())}
    @Test fun previousVersionAssetExclusionFieldsAreIgnored(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONObject("settings").put("budgetExcludeCredit",false);root.getJSONObject("settings").put("budgetExcludedAssets",org.json.JSONArray().put("missing-asset"));val restored=BackupCodec.decode(root.toString());assertTrue(restored.settings.budgetExcludedEntries.isEmpty())}
    @Test fun unknownExcludedEntryIsRejected(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONObject("settings").put("budgetExcludedEntries",org.json.JSONArray().put("missing"));assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())}}
    @Test fun unknownRepaymentEntryIsRejected(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONObject("settings").put("repaymentEntries",org.json.JSONArray().put("missing"));assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())}}
    @Test fun futureDatedEntryIsRejected(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONArray("entries").getJSONObject(0).put("date",LocalDate.now().plusDays(1).toString());assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())}}
    @Test fun negativeDeletedAtIsRejected(){val root=JSONObject(BackupCodec.encode(sample()));root.getJSONArray("entries").getJSONObject(0).put("deletedAt",-1);assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(root.toString())}}
    @Test fun todayDatedEntryIsAccepted(){val root=JSONObject(BackupCodec.encode(sample()));val today=LocalDate.now().toString();root.getJSONArray("entries").getJSONObject(0).put("date",today);root.getJSONArray("entries").getJSONObject(1).put("date",today);assertEquals(today,BackupCodec.decode(root.toString()).entries.first().date)}
    @Test fun futureDatedTransferIsRejected(){val a=AssetAccount(id="a",name="现金",kind="CASH");val b=AssetAccount(id="b",name="银行卡",kind="BANK");val t=AssetTransfer(id="t",fromAssetId="a",toAssetId="b",amount=1000,date=LocalDate.now().plusDays(1).toString());val s=sample().copy(assets=listOf(a,b),transfers=listOf(t));assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(BackupCodec.encode(s))}}
    @Test fun futureDatedAdjustmentIsRejected(){val a=AssetAccount(id="a",name="现金",kind="CASH");val adj=AssetAdjustment(id="adj",assetId="a",delta=1000,targetBalance=1000,date=LocalDate.now().plusDays(1).toString());val s=sample().copy(assets=listOf(a),adjustments=listOf(adj));assertThrows(IllegalArgumentException::class.java){BackupCodec.decode(BackupCodec.encode(s))}}
    /** v2 备份把预算标记放在 settings，恢复时必须落到账单字段上，不能丢。 */
    @Test fun legacyV2BudgetFlagsAreMigratedOntoEntries(){val root=JSONObject(BackupCodec.encode(sample()));root.put("schemaVersion",2);root.getJSONObject("settings").put("budgetExcludedEntries",org.json.JSONArray().put("original"));root.getJSONObject("settings").put("repaymentEntries",org.json.JSONArray().put("original"));val restored=BackupCodec.decode(root.toString());val origin=restored.entries.first{it.id=="original"};assertFalse(origin.inBudget);assertTrue(origin.repayment);assertEquals(0L,budgetExpense(restored.entries))}
    @Test fun poolFieldsRoundTrip(){val a=AssetAccount(id="fund",name="基金账户",kind="OTHER",openingBalance=50000,pool=POOL_INVEST);val s=sample().copy(assets=listOf(a),entries=listOf(sample().entries.first().copy(assetId="fund",pool=POOL_INVEST)));val restored=BackupCodec.decode(BackupCodec.encode(s));assertEquals(POOL_INVEST,restored.assets.single().pool);assertEquals(POOL_INVEST,restored.entries.single().pool);assertEquals(40000L,restored.assetTotal(POOL_INVEST))}
    @Test fun csvContainsPoolAndBudgetFlags(){val s=sample().copy(entries=listOf(sample().entries.first().copy(pool=POOL_INVEST,inBudget=false,repayment=true)));val csv=BackupCodec.csv(s,DateRange(LocalDate.of(2026,11,1),LocalDate.of(2026,11,30)));assertTrue(csv.contains("理财资金"));assertTrue(csv.contains("计入预算"))}
    @Test fun debtAccountWithNegativeOpeningBalanceRoundTrips(){val a=AssetAccount(id="card",name="信用卡",kind="CREDIT_CARD",openingBalance=-11000);val restored=BackupCodec.decode(BackupCodec.encode(sample().copy(assets=listOf(a))));assertEquals(-11000L,restored.assets.single().openingBalance);assertEquals(11000L,restored.assetDebtTotal());assertEquals(0L,restored.assetTotal())}
    @Test fun legacyPositiveDebtOpeningIsTreatedAsOwed(){val a=AssetAccount(id="card",name="信用卡",kind="CREDIT_CARD",openingBalance=11000,pool=POOL_INVEST);val restored=BackupCodec.decode(BackupCodec.encode(sample().copy(assets=listOf(a))));assertEquals(-11000L,restored.assets.single().openingBalance);assertEquals(POOL_LIQUID,restored.assets.single().pool);assertEquals(11000L,restored.assetDebtTotal())}
    @Test fun negativeCalibrationTargetIsAccepted(){val a=AssetAccount(id="card",name="信用卡",kind="CREDIT_CARD",openingBalance=-11000);val adj=AssetAdjustment(id="adj",assetId="card",delta=1000,targetBalance=-10000,date=LocalDate.now().toString());val restored=BackupCodec.decode(BackupCodec.encode(sample().copy(assets=listOf(a),adjustments=listOf(adj))));assertEquals(-10000L,restored.adjustments.single().targetBalance);assertEquals(-10000L,restored.assetBalances()["card"])}
}
